/**
 * @method
 * @name setParAmt
 * @description 무액면주식여부에 따른 액면금액 정의
 * @returns {void}
 * @hidden N
 */
scwin.setParAmt = function() {
    if (ckb_NPARVALSTK_YN.getValue() === "Y") {
        edt_PAR_AMT.setValue("");
        edt_PAR_AMT.setReadOnly(true);
        edt_PAR_AMT.ReadOnlyBackColor = '#b9d4f7';
    } else {
        edt_PAR_AMT.setValue(edt_PAR_AMT1.getValue());
        edt_PAR_AMT.setReadOnly(false);
        edt_PAR_AMT.ReadOnlyBackColor = 'white';
    }
};

/**
 * @method
 * @name formCheck
 * @description 폼을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.formCheck = async function() {
    if (!$c.cp.isModified(dts_detail)) {
        await $c.win.alert("변경된 데이터가 없습니다.");
        return false;
    }
    if (txb_simbol_chk.getValue() === "F") {
        await $c.win.alert("중복된 심볼입니다.");
        txb_COM_SYMBL.focus();
        return false;
    }
    if (txb_ISUR_CD.getValue() === "" || txb_ISUR_CD.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_DOM_FORN_STKCERT_TP_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "국내/외국주권 종류"));
        cmb_DOM_FORN_STKCERT_TP_CD.focus();
        return false;
    }
    if (txb_ISU_KOR_NM.getValue() === "" || txb_ISU_KOR_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목명"));
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_NM, 80, "한글종목명")) {
        // txb_ISU_KOR_NM.value = "";
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if (txb_ISU_KOR_ABBRV.getValue() === "" || txb_ISU_KOR_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "한글종목약명"));
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_KOR_ABBRV, 40, "한글종목약명")) {
        // txb_ISU_KOR_ABBRV.value = "";
        txb_ISU_KOR_ABBRV.focus();
        return false;
    }
    if (txb_ISU_ENG_NM.getValue() === "" || txb_ISU_ENG_NM.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목명"));
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_NM, 80, "영문종목명")) {
        // txb_ISU_ENG_NM.value = "";
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if (txb_ISU_ENG_ABBRV.getValue() === "" || txb_ISU_ENG_ABBRV.getValue().indexOf(" ") === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "영문종목약명"));
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_ISU_ENG_ABBRV, 40, "영문종목약명")) {
        // txb_ISU_ENG_ABBRV.value = "";
        txb_ISU_ENG_ABBRV.focus();
        return false;
    }

    // 복수의결권주는 존속기한, 의결권수 필수입력
    if (dts_detail.getCellData(dts_detail.getRowPosition(), "STKCERT_KIND_TP_CD") === "M") {
        if (edt_CONTIN_DEADLINE_STRT_DD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "존속기한 시작일자"));
            edt_CONTIN_DEADLINE_STRT_DD.focus();
            return false;
        }
        if (edt_CONTIN_DEADLINE_END_DD.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "존속기한 종료일자"));
            edt_CONTIN_DEADLINE_END_DD.focus();
            return false;
        }
        if (edt_VOTERGHT_CNT.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "의결권수"));
            edt_VOTERGHT_CNT.focus();
            return false;
        }
        if (edt_VOTERGHT_CNT.getValue() <= 0) {
            await $c.win.alert("의결권수는 0보다 큰 값을 입력하세요.");
            edt_VOTERGHT_CNT.focus();
            return false;
        }
    }
    if (fn_CheckDateObj(edt_CONTIN_DEADLINE_STRT_DD, "존속기한 시작일자")) return false;
    if (fn_CheckDateObj(edt_CONTIN_DEADLINE_END_DD, "존속기한 종료일자")) return false;
    if (cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "시장구분"));
        cmb_SPOT_ISU_TRD_MKT_TP_CD.focus();
        return false;
    }
    if (cmb_LIST_STAT_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장여부"));
        cmb_LIST_STAT_CD.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_NUSUAL_ISU_COND_CONTN, 60, "특이발행조건")) {
        // txb_ISU_ENG_ABBRV.value = "";
        txa_NUSUAL_ISU_COND_CONTN.focus();
        return false;
    }

    // CFI체크
    if (cmb_cb_p_group.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_그룹"));
        cmb_cb_p_group.focus();
        return false;
    }
    if (cmb_cb_p_attr_1.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_1차속성"));
        cmb_cb_p_attr_1.focus();
        return false;
    }
    if (cmb_cb_p_attr_2.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_2차속성"));
        cmb_cb_p_attr_2.focus();
        return false;
    }
    if (cmb_cb_p_attr_3.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_3차속성"));
        cmb_cb_p_attr_3.focus();
        return false;
    }
    if (cmb_cb_p_attr_4.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "CFI_4차속성"));
        cmb_cb_p_attr_4.focus();
        return false;
    }
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();
};

/**
 * @method
 * @name changeCfi
 * @description cfi 변경 설정
 * @returns {void}
 * @hidden N
 */
scwin.changeCfi = function() {
    // Cfi의 콤보 박스를 변경할 경우....
    let cfi = "";
    let str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
    let temp = cmb_cb_p_group.getValue(); // 선택된그룹

    // 카테고리셋팅
    if (temp === "") {
        cfi = "_";
    } else if (temp === "I" || temp === "B" || temp === "E") {
        cfi = "C";
    } else {
        cfi = "E";
    }

    // 그룹
    if (cmb_cb_p_group.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_group.getValue();

    // 1차속성
    if (cmb_cb_p_attr_1.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_1.getValue();

    // 2차속성
    if (cmb_cb_p_attr_2.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_2.getValue();

    // 3차속성
    if (cmb_cb_p_attr_3.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_3.getValue();

    // 4차속성
    if (cmb_cb_p_attr_4.getValue() === "") cfi += "_";

    else cfi += cmb_cb_p_attr_4.getValue();
    txb_CFI_CD.setValue(cfi); // cfi 설정

};

/**
 * @method
 * @name setChange
 * @description 상세 조회시 CFI 상세 설정
 * @param {String} str_cfi str_cfi
 * @returns {void}
 * @hidden N
 */
scwin.setChange = function(str_cfi) {
    if (str_cfi === "") return;
    let temp = str_cfi.substring(0, 2);
    ins_cfi_set(dts_cfi_group, "ULDINS15000.xml", SCREN_PROCS_TP_CD_01, "02", "E", "", "", "G");
    ins_cfi_set(dts_cfi_group_1, "ULDINS15000.xml", SCREN_PROCS_TP_CD_01, "02", "C", "", "", "G");

    // 하나의 데이터셋으로 합치기
    dts_cfi_group.setBroadcast(false);
    for (let i = 2; i < dts_cfi_group_1.getRowCount() + 1; i++) {
        dts_cfi_group.insertRow();
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "VALUE", dts_cfi_group_1.getCellData(i, "VALUE"));
        dts_cfi_group.setCellData(dts_cfi_group.getRowCount(), "TEXT", dts_cfi_group_1.getCellData(i, "TEXT"));
    }
    dts_cfi_group.setBroadcast(true, true);
    cmb_cb_p_group.setValue(str_cfi.substring(1, 2));
    cmb_cb_p_attr_1.setValue(str_cfi.substring(2, 3));
    cmb_cb_p_attr_2.setValue(str_cfi.substring(3, 4));
    cmb_cb_p_attr_3.setValue(str_cfi.substring(4, 5));
    cmb_cb_p_attr_4.setValue(str_cfi.substring(5, 6));
};

/**
 * @method
 * @name ins_modify
 * @description 주권 표준코드  수정한다.
 * @returns {Promise<void>}
