    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_modify",
        action : "/StdCdStkInfoAction.do",
        ref : "dts_Rst,dts_detail",
        target : "trs_modify=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name makeFisn
 * @description FISN생성
 * @returns {void}
 * @hidden N
 */
scwin.makeFisn = function() {
    // alert(getObjectValue(txb_NEWSTK_ISU_TP_CONTN));
    // alert(dts_detail.NameValue(dts_detail.RowPosition,"CFI_CD"));
    let str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
    let temp = '';
    const temp_c = str_cfi.substring(0, 1); // 카테고리 cfi첫자리
    const temp_g = cmb_cb_p_group.getValue(); // 선택한 그룹
    const temp_a1 = cmb_cb_p_attr_1.getValue(); // 선택한 1차속성
    const temp_a2 = cmb_cb_p_attr_2.getValue(); // 선택한 2차속성
    const temp_a3 = cmb_cb_p_attr_3.getValue(); // 선택한 3차속성
    const temp_a4 = cmb_cb_p_attr_4.getValue(); // 선택한 4차속성
    const temp_curr = cmb_CURR_TP_CD.getValue(); // 선택한 발행통화

    if (temp_c === "E") {
        // E: 보통주, 우선주, 합자조합 카테고리
        if (temp_g === "S" || temp_g === "C" || temp_g === "Y" || temp_g === "M") {
            // 보통주 그룹
            temp += "Com Sh";
            if (temp_a1 === "N") {
                // 1차속성 무의결권(N)
                temp += " NVTG";
            }
            if (temp_a3 === "P") {
                // 3차속성 부분납입(P)
                temp += " PP";
            }
            if (temp_a2 === "T") {
                // 2차속성 제한있음(T)
                temp += " Rstd";
            } else if (temp_a2 === "U") {
                // 2차속성 제한없음(U)
                temp += " Unrestr";
            }
            temp += " " + edt_PAR_AMT.getValue(); // 액면금액

        } else if (temp_g === 'P' || temp_g === 'F') {
            // 우선주 그룹
            if (temp_g === "F") {
                // 그룹 전환우선주(F)
                temp += "Cv";
            } else {
                temp += "";
            }
            temp += " Pref";
        } else if (temp2 === 'L') {
            // 합자조합 그룹
            temp += "Ltd Pshp";
            if (temp_a3 === "O") {
                // 3차속성 무납입(O)
                temp += " Nl Pd";
            } else if (temp_a3 === "P") {
                // 3차속성 부분납입(P)
                temp += " PP";
            } else if (temp_a3 === "F") {
                // 3차속성 전액납입(F)
                temp += " FPd";
            }
            if (temp_curr === "1") {
                // 발행통화
                temp += " KRW";
            } else if (temp_curr === "2") {
                temp += " USD";
            } else if (temp_curr === "3") {
                temp += " JPY";
            } else if (temp_curr === "4") {
                temp += " EUR";
            } else if (temp_curr === "5") {
                temp += " CNY";
            } else if (temp_curr === "6") {
                temp += " GBP";
            } else if (temp_curr === "7") {
                temp += " HKD";
            } else if (temp_curr === "8") {
                temp += " AUD";
            } else if (temp_curr === "9") {
                temp += " SGD";
            }
        }
    } else if (temp_c === 'C') {
        // C: 집합투자증권 카테고리
        if (temp_g === "B") {
            // 그룹 부동산투자회사(B)
            temp += "CIV REIT";
        } else if (temp_g === "E") {
            // 그룹 ETF(E)
            temp += "CIV ETF";
        } else if (temp_g === "I") {
            // 그룹 증권투자회사, 선박투자회사 - 스탠다드/뮤추얼펀드(I)
            temp += "CIV";
        }
        if (temp_curr === "1") {
            // 발행통화
            temp += " KRW";
        } else if (temp_curr === "2") {
            temp += " USD";
        } else if (temp_curr === "3") {
            temp += " JPY";
        } else if (temp_curr === "4") {
            temp += " EUR";
        } else if (temp_curr === "5") {
            temp += " CNY";
        } else if (temp_curr === "6") {
            temp += " GBP";
        } else if (temp_curr === "7") {
            temp += " HKD";
        } else if (temp_curr === "8") {
            temp += " AUD";
        } else if (temp_curr === "9") {
            temp += " SGD";
        }
    }

    // 최종결과 FISN setting
    txb_fisn2.setValue(temp);
};

