/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = function(rowcount) {
    // ckb_NPARVALSTK_YN.checked = false;
    if (rowcount > 0) {
        // alert(dts_detail.NameValue(dts_detail.rowpositon,"PAR_AMT"));

        let str_cfi = dts_detail.getCellData(dts_detail.rowpositon, "CFI_CD");
        scwin.setChange(str_cfi);
        edt_PAR_AMT1.setValue(edt_PAR_AMT.getValue());

        // alert(dts_detail.NameValue(dts_detail.rowpositon,"NPARVALSTK_YN"));
        if (dts_detail.getCellData(dts_detail.rowpositon, "NPARVALSTK_YN") === "Y") {
            ckb_NPARVALSTK_YN.setValue("Y");
            ckb_NPARVALSTK_YN.setValue(1);
        } else {
            ckb_NPARVALSTK_YN.setValue("N");
            ckb_NPARVALSTK_YN.setValue(0);
        }
        scwin.setParAmt();
        fn_CtrlBtn_temp("update");
        let checkflag = false;
        if ((cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "1" || cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "2" || cmb_SPOT_ISU_TRD_MKT_TP_CD.getValue() === "6") &&
            cmb_LIST_STAT_CD.getValue() === "Y") {
            // alert( "상장종목은 수정할 수 없습니다. 공시총괄팀과 협의하시기 바랍니다.");
            btn_modify.setDisabled(true);
            btn_modify.setBackgroundImage("../img/ins/btn_modify_d.gif");
            btn_delete.setDisabled(true);
            btn_delete.setBackgroundImage("../img/ins/btn_delete_d.gif");

            // alert 삭제 및 비밀번호 초기화도 제어 추가 20140116
            btn_clearPwd.setDisabled(true);
            btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd_d.gif");
            checkflag = true;
        } else {
            btn_modify.setDisabled(false);
            btn_modify.setBackgroundImage("../img/ins/btn_modify.gif");
            btn_delete.setDisabled(false);
            btn_delete.setBackgroundImage("../img/ins/btn_delete.gif");
            btn_clearPwd.setDisabled(false);
            btn_clearPwd.setBackgroundImage("../img/ins/btn_clearPwd.gif");

            // checkflag = true;

        }
        if (checkflag === false) {
            if (txb_NEWSTK_ISU_TP_CONTN.getValue() === "000") {
                // 보통주는 삭제불가
                btn_delete.setDisabled(true);
                btn_delete.setBackgroundImage("../img/ins/btn_delete_d.gif");
            } else {
                btn_delete.setDisabled(false);
                btn_delete.setBackgroundImage("../img/ins/btn_delete.gif");
            }
        }

        /*
         * 주권종류에따른 항목 활성/비활성.(존속기한, 의결권수)
         * 보통주는 비활성, 종류주식, 복수의결권은 활성
         */
        const STKCERT_KIND_TP_CD = dts_detail.getCellData(dts_detail.getRowPosition(), "STKCERT_KIND_TP_CD");
        // 보통주
        if (STKCERT_KIND_TP_CD === "C") {
            scwin.ctrlObjByStkcertKind(false);
        } else {
            scwin.ctrlObjByStkcertKind(true);
        }
    } else {
        scwin.setChange("");
        fn_CtrlBtn_temp("no_data");
    }
};

