/**
 * @method
 * @name dts_COM_ATTR_TP_CD_OnLoadCompleted
 * @description dts_COM_ATTR_TP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_COM_ATTR_TP_CD_OnLoadCompleted = function(rowcount) {
    dts_COM_ATTR_TP_CD.setBroadcast(false);
    for (let i = dts_COM_ATTR_TP_CD.getRowCount(); i > 0; i--) {
        if (dts_COM_ATTR_TP_CD.getCellData(i, "VALUE") === "1") {
            dts_COM_ATTR_TP_CD.setCellData(i, "TEXT", "1 주식회사");
        } else if (dts_COM_ATTR_TP_CD.getCellData(i, "VALUE") === "2") {
            dts_COM_ATTR_TP_CD.setCellData(i, "TEXT", "2 증권투자회사");
        }
    }
    dts_COM_ATTR_TP_CD.setBroadcast(true, true);
};

