/**
 * @method
 * @name cmb_cb_p_group_onselchange
 * @description cmb_cb_p_group onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_cb_p_group_onselchange = function() {
    if (cmb_cb_p_group.getValue() !== "") {
        let str_cfi = dts_detail.getCellData(dts_detail.getRowPosition(), "CFI_CD");
        const temp1 = ""; // str_cfi.substring(0, 1);//카테고리 cfi첫자리
        const temp2 = cmb_cb_p_group.getValue(); // 선택한 그룹
        let productDiv = "";
        let categoryDiv = "";

        // 그룹에따라 [상품구분, 카테고리] 셋팅
        productDiv = "02";
        if (temp2 === "S" || temp2 === "C" || temp2 === "Y" || temp2 === "M") {
            // 보통주, 전환보통주, 구조화증권, 기타
            categoryDiv = "E";
        } else if (temp2 === "P" || temp2 === "F") {
            // 우선주, 전환우선주
            categoryDiv = "E";
        } else if (temp2 === "I" || temp2 === "B" || temp2 === "E") {
            // 증권투자, 선박투자, 부동산투자, ETF
            categoryDiv = "C";
        } else if (temp2 === "L") {
            // 합자조합
            categoryDiv = "E";
        }
        ins_cfi_set(dts_cfi_attr1, "ULDINS15000.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, cmb_cb_p_group.getValue(), "1", "");
        ins_cfi_set(dts_cfi_attr2, "ULDINS15000.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, cmb_cb_p_group.getValue(), "2", "");
        ins_cfi_set(dts_cfi_attr3, "ULDINS15000.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, cmb_cb_p_group.getValue(), "3", "");
        ins_cfi_set(dts_cfi_attr4, "ULDINS15000.xml", SCREN_PROCS_TP_CD_01, productDiv, categoryDiv, cmb_cb_p_group.getValue(), "4", "");
        // alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        label_attr1.setValue("(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        label_attr2.setValue("(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        label_attr3.setValue("(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        label_attr4.setValue("(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.changeCfi();
};

